//     check(32'he0, 32'h000001b0);  // jal link address
//     check(32'he4, 32'h00000001);  // jal jump target executed
//     check(32'he8, 32'h000001cc);  // JALR link address (fixed from 32'h000501cc)
//     check(32'hec, 32'h00000000);  // skipped instruction

//     // ---- Register-register shifts ----
//     check(32'hf0, 32'h0e000000);  // sll
//     check(32'hf4, 32'h01ffffff);  // srl
//     check(32'hf8, 32'hffffffff);  // sra

//     if (errors == 0) $display("PASS: core produced every expected result");
//     else $display("FAIL: %0d mismatch(es)", errors);
//     $finish;
//   end
// endmodule

`timescale 1ns / 1ps
import axi_vip_pkg::*;
import tb_bd_axi_vip_0_0_pkg::*;

// =============================================================================
// SIMULATION ONLY. Runs the official riscv-tests rv32ui suite on the RV32I core
// through the AXI VIP, one test at a time:
//   hold core in reset -> write program (imem) and data (dmem) over AXI ->
//   release reset -> poll 'tohost' (dmem word 0) -> PASS if it reads 1.
//   tohost == (n << 1) | 1 means sub-test number n failed.
//
// Test sources: https://github.com/riscv-software-src/riscv-tests
//   riscv-tests commit 3df703cd52d5f0d8224e3c50bf03c6cb70efff98 (isa/rv32ui)
//   env submodule      6de71edb142be36319e380ce782c3d1830c65d68
// Test bodies are unmodified. Only the environment header was replaced (no
// CSRs / ecall): pass or fail is written to memory instead (see riscv_test.h).
// Program images were built with riscv64-unknown-elf-gcc -march=rv32i, text at
// imem 0x0, tohost+data at dmem 0x0.
//
// Skipped on purpose: fence_i (Zifencei), ma_data (misaligned access).
// =============================================================================
module tb_bram_test;
  localparam logic [31:0] IMEM_BASE = 32'hC000_8000;  // same as your working tb_bram_test
  localparam logic [31:0] DMEM_BASE = 32'hC200_0000;  // same as your working tb_bram_test

  logic clk = 0, resetn = 0;
  logic core_rst = 1;
  always #5 clk = ~clk;

  tb_bd_wrapper dut (
      .s_axi_aclk_0(clk),
      .s_axi_aresetn_0(resetn),
      .rst_0(core_rst)
  );

  tb_bd_axi_vip_0_0_mst_t master;

  task automatic axi_write32(input [31:0] addr, input [31:0] data);
    xil_axi_resp_t resp;
    bit [32767:0] wd = data;
    master.AXI4_WRITE_BURST(0, addr, 0, XIL_AXI_SIZE_4BYTE, XIL_AXI_BURST_TYPE_INCR,
                            XIL_AXI_ALOCK_NOLOCK, 0, 0, 0, 0, 0, wd, 0, resp);
  endtask

  // Argument order from memory of PG267:
  // (id, addr, len, size, burst, lock, cache, prot, region, qos, aruser, data, resp, ruser)
  task automatic axi_read32(input [31:0] addr, output [31:0] data);
    xil_axi_resp_t resp;
    bit [32767:0] rd;
    bit [31:0] ruser;
    master.AXI4_READ_BURST(0, addr, 0, XIL_AXI_SIZE_4BYTE, XIL_AXI_BURST_TYPE_INCR,
                           XIL_AXI_ALOCK_NOLOCK, 0, 0, 0, 0, 0, rd, resp, ruser);
    data = rd[31:0];
  endtask

  // Images filled in by the t_<name> tasks below
  logic [31:0] imem_img[0:833];
  logic [31:0] dmem_img[ 0:23];
  int n_imem, n_dmem;

  int unsigned n_pass = 0, n_fail = 0;

  task automatic run_test(input string name);
    logic [31:0] tohost;
    int polls;
    core_rst = 1;
    repeat (5) @(posedge clk);
    for (int i = 0; i < n_imem; i++) axi_write32(IMEM_BASE + 4 * i, imem_img[i]);
    for (int i = 0; i < n_dmem; i++)
      axi_write32(DMEM_BASE + 4 * i, dmem_img[i]);  // word 0 = tohost = 0
    repeat (3) @(posedge clk);
    core_rst = 0;

    tohost = 0;
    polls = 0;
    while (tohost == 0 && polls < 1000) begin
      repeat (20) @(posedge clk);
      axi_read32(DMEM_BASE, tohost);
      polls++;
    end
    core_rst = 1;

    if (tohost == 32'h1) begin
      n_pass++;
      $display("PASS  %s", name);
    end else if (tohost == 0) begin
      logic [31:0] i0, i1, d0;
      n_fail++;
      $display("FAIL  %s : TIMEOUT (core never wrote tohost)", name);
      // Diagnostics: did the AXI writes land where we think they did?
      axi_read32(IMEM_BASE + 0, i0);
      axi_read32(IMEM_BASE + 4, i1);
      axi_read32(DMEM_BASE + 0, d0);
      $display("      imem[0]=%08h (expected %08h)  imem[1]=%08h (expected %08h)  dmem[0]=%08h",
               i0, imem_img[0], i1, imem_img[1], d0);
    end else begin
      n_fail++;
      $display("FAIL  %s : sub-test number %0d failed (tohost=%08h)", name, tohost >> 1, tohost);
    end
  endtask

